}

IedConnectionState /* <=== IedConnection_getState */ 
IedConnection_getState(IedConnection self)
{
    IedConnectionState state;

    Semaphore_wait(self->stateMutex);
    state = self->state;
    Semaphore_post(self->stateMutex);

    return state;
}

void /* <=== IedConnection_close */ 
